query GetNodePolymorphic($id: ID!) {
  node(id: $id) {
    __typename
    ... on User {
      id
      username
    }
    ... on Post {
      id
      title
    }
  }
}

query GetNode($id: ID!) {
  node(id: $id) {
    id
    ... on User {
      username
    }
  }
}

query GetUserById($id: ID!, $tags: [String!]!) {
  node(id: $id) {
    ... on User {
      id
      username
    }
  }
}

fragment AccountInfo on Account {
  __typename
  ... on User {
    username
  }
  ... on Admin {
    role
  }
}

fragment UserFields on User @public {
  id
  username
}

fragment InternalFields on User {
  email
}

